-- Beginner-facing Japanese readings. Canonical Japanese text remains in the
-- legacy `pl`, `lemma`, and inflection fields for old clients and audio; this
-- catalog adds an explicit script, kana reading, and Hepburn romaji rendition
-- for every fixed EN→JA starter-pack target.
-- Future EN→JA seed changes must preserve this payload.readings catalog because
-- the mobile clients decode it directly for the shared presentation engine.

UPDATE content_lessons
SET payload_json = json_set(payload_json, '$.readings', json('{"ありがとう":{"japanese":"ありがとう","kana":"ありがとう","romaji":"arigatō"},"いいえ":{"japanese":"いいえ","kana":"いいえ","romaji":"iie"},"すし":{"japanese":"すし","kana":"すし","romaji":"sushi"},"えき":{"japanese":"えき","kana":"えき","romaji":"eki"},"おはよう":{"japanese":"おはよう","kana":"おはよう","romaji":"ohayō"}}')), updated_at = datetime('now')
WHERE content_version_id = 'en-ja-v1' AND lesson_id = 'lesson-01';

