UPDATE content_lessons
SET payload_json = json_set(payload_json, '$.readings', json('{"おはようございます。":{"japanese":"おはようございます。","kana":"おはようございます。","romaji":"Ohayō gozaimasu."},"こんにちは。":{"japanese":"こんにちは。","kana":"こんにちは。","romaji":"Konnichiwa."},"こんばんは。":{"japanese":"こんばんは。","kana":"こんばんは。","romaji":"Konbanwa."},"おやすみなさい。":{"japanese":"おやすみなさい。","kana":"おやすみなさい。","romaji":"Oyasuminasai."},"ありがとうございます。":{"japanese":"ありがとうございます。","kana":"ありがとうございます。","romaji":"Arigatō gozaimasu."},"どういたしまして。":{"japanese":"どういたしまして。","kana":"どういたしまして。","romaji":"Dō itashimashite."},"すみません。":{"japanese":"すみません。","kana":"すみません。","romaji":"Sumimasen."},"はじめまして。":{"japanese":"はじめまして。","kana":"はじめまして。","romaji":"Hajimemashite."},"私はアレックスです。":{"japanese":"私はアレックスです。","kana":"わたしはアレックスです。","romaji":"Watashi wa Arekkusu desu."},"お名前は何ですか。":{"japanese":"お名前は何ですか。","kana":"おなまえはなんですか。","romaji":"Onamae wa nan desu ka?"},"よろしくお願いします。":{"japanese":"よろしくお願いします。","kana":"よろしくおねがいします。","romaji":"Yoroshiku onegaishimasu."},"日本語を勉強しています。":{"japanese":"日本語を勉強しています。","kana":"にほんごをべんきょうしています。","romaji":"Nihongo o benkyō shite imasu."},"日本語があまり分かりません。":{"japanese":"日本語があまり分かりません。","kana":"にほんごがあまりわかりません。","romaji":"Nihongo ga amari wakarimasen."},"もう一度言ってください。":{"japanese":"もう一度言ってください。","kana":"もういちどいってください。","romaji":"Mō ichido itte kudasai."},"英語を話せますか。":{"japanese":"英語を話せますか。","kana":"えいごをはなせますか。","romaji":"Eigo o hanasemasu ka?"},"トイレはどこですか。":{"japanese":"トイレはどこですか。","kana":"トイレはどこですか。","romaji":"Toire wa doko desu ka?"},"これはいくらですか。":{"japanese":"これはいくらですか。","kana":"これはいくらですか。","romaji":"Kore wa ikura desu ka?"},"おいしいです。":{"japanese":"おいしいです。","kana":"おいしいです。","romaji":"Oishii desu."},"おすすめはありますか。":{"japanese":"おすすめはありますか。","kana":"おすすめはありますか。","romaji":"Osusume wa arimasu ka?"},"楽しかったです。":{"japanese":"楽しかったです。","kana":"たのしかったです。","romaji":"Tanoshikatta desu."},"いい天気ですね。":{"japanese":"いい天気ですね。","kana":"いいてんきですね。","romaji":"Ii tenki desu ne."},"日本語はまだまだです。":{"japanese":"日本語はまだまだです。","kana":"にほんごはまだまだです。","romaji":"Nihongo wa madamada desu."},"ダイエットは明日からです。":{"japanese":"ダイエットは明日からです。","kana":"ダイエットはあしたからです。","romaji":"Daietto wa ashita kara desu."},"猫の手も借りたいです。":{"japanese":"猫の手も借りたいです。","kana":"ねこのてもかりたいです。","romaji":"Neko no te mo karitai desu."},"お腹と背中がくっつきそうです。":{"japanese":"お腹と背中がくっつきそうです。","kana":"おなかとせなかがくっつきそうです。","romaji":"Onaka to senaka ga kuttsukisō desu."}}')), updated_at = datetime('now')
